/* ============================================
   STAT COMPONENT
   A single headline metric with label and an
   optional trend delta. Compose in a row for
   a metrics band.
   ============================================ */

.ds-stat {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--gap-050);
}

/* ============================================
   VALUE — the display tier's weight (300 in the
   base theme), so numerals follow the theme
   ============================================ */

.ds-stat__value {
  font-family: var(--font-sub-display-family);
  font-size: var(--font-sub-display-size);
  font-weight: var(--font-sub-display-weight);
  line-height: var(--font-sub-display-line-height);
  letter-spacing: var(--font-sub-display-letter-spacing);
  color: var(--color-text-display);
}

.ds-stat--large .ds-stat__value {
  font-family: var(--font-display-2-family);
  font-size: var(--font-display-2-size);
  line-height: var(--font-display-2-line-height);
  letter-spacing: var(--font-display-2-letter-spacing);
}

/* ============================================
   LABEL
   ============================================ */

.ds-stat__label {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
}

/* ============================================
   DELTA — trend-coloured annotation
   ============================================ */

.ds-stat__delta {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-050);
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
}

.ds-stat__delta .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
  line-height: 1;
}

/* The trend tokens are theme-split for contrast: deep status inks on
   light surfaces, the mint/coral accents on dark ones. */
.ds-stat__delta--up {
  color: var(--color-trend-up);
}

.ds-stat__delta--down {
  color: var(--color-trend-down);
}

.ds-stat__delta--neutral {
  color: var(--color-text-tertiary);
}

/* ============================================
   INLINE DELTA — delta to the right of the
   value, bottom-aligned to its baseline
   ============================================ */

.ds-stat--delta-inline {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-areas:
    'value delta'
    'label label';
  column-gap: var(--gap-200);
  row-gap: var(--gap-050);
}

.ds-stat--delta-inline .ds-stat__value {
  grid-area: value;
}

.ds-stat--delta-inline .ds-stat__label {
  grid-area: label;
}

.ds-stat--delta-inline .ds-stat__delta {
  grid-area: delta;
  align-self: end;
  justify-self: start;
  /* Optical baseline: compensates the display value's half-leading. */
  margin-bottom: var(--gap-100);
}

/* ============================================
   AUTO DELTA — inline while the stat has room,
   stacked under the label once it is narrow.
   The root fills its parent and is the size
   container; the body inside it re-templates.
   ============================================ */

.ds-stat--delta-auto {
  display: block;
  width: 100%;
  min-width: 0;
  container: ds-stat / inline-size;
}

.ds-stat__body {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-areas:
    'value delta'
    'label label';
  justify-items: start;
  column-gap: var(--gap-200);
  row-gap: var(--gap-050);
}

.ds-stat__body .ds-stat__value {
  grid-area: value;
}

.ds-stat__body .ds-stat__label {
  grid-area: label;
}

.ds-stat__body .ds-stat__delta {
  grid-area: delta;
  align-self: end;
  /* The inline placement's optical baseline. */
  margin-bottom: var(--gap-100);
}

/* Too narrow for the value and its delta side by side: the delta drops
   under the label, the stacked placement's order. */
@container ds-stat (max-width: 180px) {
  .ds-stat__body {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      'value'
      'label'
      'delta';
  }

  .ds-stat__body .ds-stat__delta {
    align-self: start;
    margin-bottom: 0;
  }
}

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents. */
.ds-stat .material-symbols-rounded {
  color: inherit;
}

import React from 'react';
import './Stat.css';
import '../../fonts/material-symbols.css';
import { DEFAULT_LOCALE, formatNumber } from '../../behaviors/locale';

/** Props owned by Stat itself — everything else falls through to the root div. */
type StatOwnProps = {
  /** The headline number, e.g. "~900%" or "3.8M" — or a node, such as an AnimatedNumber, for figures that move */
  value: React.ReactNode;
  /** What the number measures */
  label: string;
  /** Optional change annotation, e.g. "+42% vs last quarter" */
  delta?: string;
  /** Direction of the delta — colours it and adds an arrow */
  trend?: 'up' | 'down' | 'neutral';
  /**
   * Where the delta sits: stacked below the label, inline to the right of the
   * value (bottom-aligned), or `auto`: inline while the stat has room and
   * stacked once it is narrow, such as a KPI tile in a two-up phone grid.
   * `auto` fills its parent's width and reads its own, so it restacks
   * wherever it sits, whatever the viewport.
   */
  deltaPlacement?: 'stacked' | 'inline' | 'auto';
  /** Stat size */
  size?: 'default' | 'large';
  /** The BCP 47 locale a number `value` is written in, such as `ar-EG`. Defaults to `en-US`. This component can render from a Server Component, so it takes the prop alone and reads no LocaleProvider. */
  locale?: string;
  /** Additional CSS classes */
  className?: string;
};

export interface StatProps
  extends StatOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof StatOwnProps | 'children'> {}

const TREND_ICONS: Record<NonNullable<StatOwnProps['trend']>, string> = {
  up: 'arrow_upward',
  down: 'arrow_downward',
  neutral: 'remove',
};

/**
 * Stat component — a single headline metric with a label and an
 * optional trend delta. Compose several in a row for a metrics band.
 * Forwards a ref to the root div and spreads native attributes onto it.
 */
export const Stat = React.forwardRef<HTMLDivElement, StatProps>(
  (
    {
      value,
      label,
      delta,
      trend = 'neutral',
      deltaPlacement = 'stacked',
      size = 'default',
      locale = DEFAULT_LOCALE,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-stat';

    const classes = [
      baseClass,
      `${baseClass}--${size}`,
      deltaPlacement === 'inline' ? `${baseClass}--delta-inline` : '',
      deltaPlacement === 'auto' ? `${baseClass}--delta-auto` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const parts = (
      <>
        <span className={`${baseClass}__value`}>{typeof value === 'number' ? formatNumber(value, locale) : value}</span>
        <span className={`${baseClass}__label`}>{label}</span>
        {delta && (
          <span className={`${baseClass}__delta ${baseClass}__delta--${trend}`}>
            <span className="material-symbols-rounded" aria-hidden="true">
              {TREND_ICONS[trend]}
            </span>
            {delta}
          </span>
        )}
      </>
    );

    return (
      <div {...rest} ref={ref} className={classes}>
        {/* A container query styles only what sits inside the container,
            so `auto` lays its parts out on an inner body the root measures. */}
        {deltaPlacement === 'auto' ? <span className={`${baseClass}__body`}>{parts}</span> : parts}
      </div>
    );
  },
);

Stat.displayName = 'Stat';
